// AUTO-GENERATED country reference data (ISO 3166-1).
// Maps a visitor country (ISO alpha-2, from the x-vercel-ip-country header) to a
// display name and the ISO 3166-1 numeric code used by the world-atlas TopoJSON
// (leading zeros stripped, e.g. "004" -> "4"), so map regions can be matched to
// analytics counts. Do not edit by hand — regenerate from the ISO 3166 dataset.

export interface CountryInfo {
  name: string;
  /** ISO 3166-1 numeric code (no leading zeros) — matches world-atlas feature ids. */
  numeric: string;
}

