/** Reverse lookup: world-atlas numeric id -> alpha-2 code. */
export const NUMERIC_TO_ALPHA2: Record<string, string> = Object.fromEntries(
  Object.entries(COUNTRIES).map(([a2, info]) => [info.numeric, a2]),
);

/** Human-readable country name for an alpha-2 code (falls back to the code). */
export function countryName(alpha2: string | null | undefined): string {
  if (!alpha2) return "Unknown";
  return COUNTRIES[alpha2.toUpperCase()]?.name ?? alpha2.toUpperCase();
}

/**
 * Flag emoji for an alpha-2 code, built from Unicode regional indicator symbols.
 * Returns a globe for unknown / non-country codes.
 */
export function countryFlag(alpha2: string | null | undefined): string {
  const code = alpha2?.toUpperCase();
  if (!code || code.length !== 2 || !/^[A-Z]{2}$/.test(code)) return "🌐";
  const A = 0x1f1e6;
  return String.fromCodePoint(
    A + (code.charCodeAt(0) - 65),
    A + (code.charCodeAt(1) - 65),
  );
}
